import { describe, expect, it } from "vitest";
import { Chess, validateFen } from "chess.js";
import { parsePosition } from "../engine/positions";
import bank from "./puzzle-bank.json";

// Generated by scripts/puzzle-bank.mjs. These checks use chess.js's public API only, so they do not
// share code with the generator's search.

type Puzzle = { id: string; fen: string; moves: string[]; mateIn: 1 | 2; theme: string; rating: number };

const puzzles = bank as Puzzle[];
const THEMES = ["backRank", "smothered", "queen", "rook", "knight", "bishop", "pawn", "promotion", "doubleCheck", "mixed"];

const asMove = (uci: string) => ({ from: uci.slice(0, 2), to: uci.slice(2, 4), promotion: uci[4] });

function givesMate(chess: Chess, move: { from: string; to: string; promotion?: string }): boolean {
  chess.move(move);
  const mate = chess.isCheckmate();
  chess.undo();
  return mate;
}

/** Every mating move for the side to move, in UCI. A mate is a check, so only checks are played out. */
function matingMoves(chess: Chess): string[] {
  return chess
    .moves({ verbose: true })
    .filter((move) => /[+#]$/.test(move.san) && givesMate(chess, move))
    .map((move) => move.lan);
}

function hasMate(chess: Chess): boolean {
  return chess.moves({ verbose: true }).some((move) => /[+#]$/.test(move.san) && givesMate(chess, move));
}

/** After a key move: the defender has a move, and every one of them allows mate next move. */
function forcesMate(chess: Chess): boolean {
  const defences = chess.moves({ verbose: true });
  return (
    defences.length > 0 &&
    defences.every((defence) => {
      chess.move(defence);
      const mate = hasMate(chess);
      chess.undo();
      return mate;
    })
  );
}

/** Moves that mate on the next move against every defence. */
function keyMoves(chess: Chess): string[] {
  return chess
    .moves({ verbose: true })
    .filter((key) => {
      chess.move(key);
      const forced = forcesMate(chess);
      chess.undo();
      return forced;
    })
    .map((key) => key.lan);
}

describe("puzzle bank", () => {
  it("has unique ids and enough mates in one and two", () => {
    expect(new Set(puzzles.map((puzzle) => puzzle.id)).size).toBe(puzzles.length);
    expect(puzzles.filter((puzzle) => puzzle.mateIn === 1).length).toBeGreaterThanOrEqual(100);
    expect(puzzles.filter((puzzle) => puzzle.mateIn === 2).length).toBeGreaterThanOrEqual(25);
  });

  it("uses known themes and ratings, sorted from easiest to hardest", () => {
    for (const puzzle of puzzles) {
      expect(THEMES).toContain(puzzle.theme);
      expect([1, 2]).toContain(puzzle.mateIn);
      expect(Number.isInteger(puzzle.rating) && puzzle.rating >= 400 && puzzle.rating <= 1800).toBe(true);
    }
    const ratings = puzzles.map((puzzle) => puzzle.rating);
    expect(ratings).toEqual([...ratings].sort((a, b) => a - b));
  });

  it.each(puzzles)("$id ($theme, mate in $mateIn) has exactly one solution", (puzzle) => {
    const { fen, moves, mateIn } = puzzle;

    // A legal position the app accepts as it is.
    expect(validateFen(fen).ok).toBe(true);
    expect(parsePosition(fen)).toEqual({ ok: true, fen });
    const chess = new Chess(fen);
    expect(chess.isCheckmate()).toBe(false);

    // It looks like a game: at least seven men besides the king each, no pawn on an end rank, kings apart.
    const pieces = chess.board().flat().filter((cell) => cell !== null);
    for (const color of ["w", "b"]) expect(pieces.filter((cell) => cell.color === color && cell.type !== "k").length).toBeGreaterThanOrEqual(7);
    expect(pieces.some((cell) => cell.type === "p" && /[18]/.test(cell.square))).toBe(false);
    const [a, b] = pieces.filter((cell) => cell.type === "k").map((cell) => [cell.square.charCodeAt(0), Number(cell.square[1])]);
    expect(Math.max(Math.abs(a[0] - b[0]), Math.abs(a[1] - b[1]))).toBeGreaterThan(1);

    expect(moves).toHaveLength(2 * mateIn - 1);
    if (mateIn === 1) {
      expect(matingMoves(chess)).toEqual([moves[0]]);
    } else {
      expect(hasMate(chess)).toBe(false);
      expect(keyMoves(chess)).toEqual([moves[0]]);
    }

    // The stored line (key, defence, mate) is legal and ends in checkmate.
    for (const uci of moves) expect(() => chess.move(asMove(uci))).not.toThrow();
    expect(chess.isCheckmate()).toBe(true);
  }, 20_000);
});
